y=dP_dt; sq=np.sqrt(P); one=np.ones_like(P)
res=[]
for m in [0.5,1,1.5,2,3]:
  for kind in ['exp','sin','cos','lin_exp','pow']:
    for w in np.linspace(-1.5,1.5,61):
        if w==0 and kind!='lin_exp': continue
        if kind=='exp': f=np.exp(w*t)
        elif kind=='sin': f=np.sin(w*t)
        elif kind=='cos': f=np.cos(w*t)
        elif kind=='lin_exp': f=t*np.exp(w*t)
        else: f=t**(w+1.5)
